mapper.select:
SELECT (feature_ver IS NOT DISTINCT FROM #{featureVersion}
        AND model_config IS NOT DISTINCT FROM CAST(#{modelConfigJson} AS JSONB))
FROM tb_model_bundle
WHERE model_bundle_id = #{modelBundleId}

SELECT COALESCE(MAX(config_ver), 0)
FROM tb_camera_config
WHERE camera_id = #{cameraId}
